import { useContext, useEffect, useState } from "react";
import { Contextapi } from "./Contextapi";

function Cart() {
    const [cartdata, setCartData] = useState([])
    const { cart } = useContext(Contextapi)
    let amount =0
    //console.log(cart)
    useEffect(() => {
        fetch('/api/cart', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ids: Object.keys(cart.item) })
        }).then((resp) => { return resp.json() }).then((data) => {
            //console.log(data)
            if (data.status === 200) {
                setCartData(data.apiData)
            } else {
                console.log(error.message)
            }
        })
    }, [])
    function handleqty(id){
        return cart.item[id]
    }
  function handleprice(id,price){
        let producprice= handleqty(id)*price
        amount +=price 
        return producprice
  }
    return (
        <section id="cart">
            <div className="container">
                <div className="row">
                    <div className="col-md-12">
                        <tabel className='table table-hover'>
                            <thead>
                                <tr>
                                    <th>s. no</th>
                                    <th>product name</th>
                                    <th>product quantity</th>
                                    <th>price</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                {cartdata.map((result, kk) => (
                                    <tr key={result._id}>
                                        <td>{kk+1}</td>
                                        <td>{result.name}</td>
                                        <td>{handleqty(result._id)}</td>
                                        <td>{handleprice(result._id,result.price)}</td>
                                        <td></td>


                                    </tr>
                                ))}
                                <tr>
                            <td colSpan={5}><h4>Total Amount:{amount}</h4></td>
                                </tr>



                            </tbody>
                        </tabel >
                    </div>
                </div>
            </div>
        </section>

    );
}

export default Cart;
